impl<T: crate::Float> Length<T> {
    /// The value in the largest SI-prefixed form of the base unit that doesn't
    /// exceed it, in steps of 1000 (`fm`, `pm`, `nm`, `µm`, `mm`, `m`, `km`, `Mm`, `Gm`).
    /// Zero, NaN and infinities stay in the base unit.
    #[inline]
    pub fn auto_unit(self) -> crate::InUnit<T, LengthUnit> {
        const SCALE: [(f64, LengthUnit); 9] = [
            (1e9, LengthUnit::Gigameter),
            (1000000.0, LengthUnit::Megameter),
            (1000.0, LengthUnit::Kilometer),
            (1.0, LengthUnit::Meter),
            (0.001, LengthUnit::Millimeter),
            (1e-6, LengthUnit::Micrometer),
            (1e-9, LengthUnit::Nanometer),
            (1e-12, LengthUnit::Picometer),
            (1e-15, LengthUnit::Femtometer),
        ];
        crate::__private::auto_unit(self, &SCALE)
    }
}

